import 'package:cephalopod/features/game/presentation/models/computer_choices_ui.dart';
import 'package:cephalopod/features/game/presentation/models/opponent_ui.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'new_game_view_state.freezed.dart';

/// Everything the new-game dialog shows: the [opponent] chosen and, when it
/// is the computer, the [computerChoices] for it. Against a friend there is
/// nothing more to choose, so there are none.
///
/// A UI model (docs/adr/0015): plain data generated by freezed
/// (docs/adr/0011).
@freezed
abstract class NewGameViewState with _$NewGameViewState {
  const factory NewGameViewState({
    required OpponentUi opponent,
    ComputerChoicesUi? computerChoices,
  }) = _NewGameViewState;
}
